package main

import (
	"fmt"
	"os"
)

// Simulating the bitarray structure and functions
type block uint64
const s = 64

type bitArray struct {
	blocks  []block
	lowest  uint64
	highest uint64
	anyset  bool
}

func (ba *bitArray) setLowest() {
	for i := uint64(0); i < uint64(len(ba.blocks)); i++ {
		if ba.blocks[i] == 0 {
			continue
		}

		// Simplified findRightPosition for testing
		pos := uint64(0)
		temp := ba.blocks[i]
		for temp&1 == 0 {
			temp >>= 1
			pos++
		}

		ba.lowest = (i * s) + pos
		ba.anyset = true
		return
	}

	ba.anyset = false
	ba.lowest = 0
	// Fixed: Don't modify highest here
	// ba.highest = 0
}

func (ba *bitArray) setHighest() {
	for i := len(ba.blocks) - 1; i >= 0; i-- {
		if ba.blocks[i] == 0 {
			continue
		}

		// Simplified findLeftPosition for testing
		pos := uint64(0)
		temp := ba.blocks[i]
		for temp != 0 {
			temp >>= 1
			pos++
		}
		pos-- // Adjust for 0-based indexing

		ba.highest = (uint64(i) * s) + pos
		ba.anyset = true
		return
	}

	ba.anyset = false
	ba.highest = 0
	// Fixed: Don't modify lowest here
	// ba.lowest = 0
}

func main() {
	// Create a bitArray instance
	ba := &bitArray{
		blocks:  make([]block, 2),
		lowest:  5,
		highest: 100,
		anyset:  true,
	}

	fmt.Printf("Initial state: lowest=%d, highest=%d, anyset=%t\n", ba.lowest, ba.highest, ba.anyset)

	// Call setLowest when there are no set bits
	ba.setLowest()
	fmt.Printf("After setLowest: lowest=%d, highest=%d, anyset=%t\n", ba.lowest, ba.highest, ba.anyset)

	// Reset values
	ba.lowest = 5
	ba.highest = 100
	ba.anyset = true
	fmt.Printf("Reset state: lowest=%d, highest=%d, anyset=%t\n", ba.lowest, ba.highest, ba.anyset)

	// Call setHighest when there are no set bits
	ba.setHighest()
	fmt.Printf("After setHighest: lowest=%d, highest=%d, anyset=%t\n", ba.lowest, ba.highest, ba.anyset)

	// Check if the fix works correctly
	if ba.highest != 100 {
		fmt.Println("ERROR: highest was incorrectly modified in setLowest")
		os.Exit(1)
	}

	if ba.lowest != 5 {
		fmt.Println("ERROR: lowest was incorrectly modified in setHighest")
		os.Exit(1)
	}

	fmt.Println("Fix verified successfully!")
}
EOF
```

